import{_ as r,o as a,c as n,ag as t}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"de/faq.md","filePath":"de/faq.md"}'),i={name:"de/faq.md"};function d(o,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="die-konsole-meldet-you-lack-the-required-entitlement" tabindex="-1">Die Konsole meldet <code>You lack the required entitlement</code> <a class="header-anchor" href="#die-konsole-meldet-you-lack-the-required-entitlement" aria-label="Permalink to &quot;Die Konsole meldet `You lack the required entitlement`&quot;">​</a></h2><p>Das Skript ist nicht mit dem Cfx.re Konto verknüpft, dem der Lizenzschlüssel deines Servers gehört. Prüfe im <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a>, ob das Konto, das das Skript gekauft hat, auch den Schlüssel in <code>sv_licenseKey</code> erstellt hat. Die Berechtigungen (Entitlements) werden beim Serverstart gelesen: Starte nach einem neuen Kauf den ganzen Server neu, ein <code>restart</code> der Ressource reicht nicht.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p><code>nay_lib</code> muss vor jedem Nayretis Skript starten, und beide Ordner müssen in deinem Ordner <code>resources</code> liegen. Prüfe die Reihenfolge der <code>ensure</code> Zeilen in der <code>server.cfg</code>: <code>ensure nay_lib</code> kommt zuerst, nach deinen Framework-, Inventar- und Target-Ressourcen.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Starte <code>nay_lib</code> nach deiner Framework-Ressource. Schlägt die Erkennung trotzdem fehl, erzwinge das Framework in der <code>server.cfg</code>, zum Beispiel mit <code>setr nay:framework &quot;esx&quot;</code>. Die möglichen Werte stehen auf der Seite <a href="/de/bridge/">Bridge</a>. Dein Framework wird nicht unterstützt? Schreibe einen <a href="/de/bridge/custom">eigenen Adapter</a>.</p><h2 id="datenbankfehler-beim-start" tabindex="-1">Datenbankfehler beim Start <a class="header-anchor" href="#datenbankfehler-beim-start" aria-label="Permalink to &quot;Datenbankfehler beim Start&quot;">​</a></h2><p><code>oxmysql</code> muss vor <code>nay_lib</code> gestartet und mit deiner Datenbank verbunden sein (<code>mysql_connection_string</code> in der <code>server.cfg</code>). Die Tabellen werden beim ersten Start angelegt, der Datenbankbenutzer braucht also das Recht, Tabellen zu erstellen.</p><h2 id="wie-andere-ich-die-sprache" tabindex="-1">Wie ändere ich die Sprache? <a class="header-anchor" href="#wie-andere-ich-die-sprache" aria-label="Permalink to &quot;Wie ändere ich die Sprache?&quot;">​</a></h2><p>Öffne <code>/nay</code>, dann <strong>Nayretis</strong>, dann <strong>Sprache</strong>. Englisch, Französisch, Spanisch, Portugiesisch, Polnisch und Deutsch sind enthalten, und die Sprache gilt für jedes Nayretis Skript. <code>setr nay:locale &quot;fr&quot;</code> in der <code>server.cfg</code> legt die Sprache fest, die gilt, bis jemand sie im Spiel ändert.</p><h2 id="welche-dateien-darf-ich-bearbeiten" tabindex="-1">Welche Dateien darf ich bearbeiten? <a class="header-anchor" href="#welche-dateien-darf-ich-bearbeiten" aria-label="Permalink to &quot;Welche Dateien darf ich bearbeiten?&quot;">​</a></h2><ul><li><code>config.lua</code> jedes Skripts: optionale Startwerte. Sie gelten, bis eine Einstellung in <code>/nay</code> geändert wird, und <strong>Zurücksetzen</strong> kehrt zu ihnen zurück.</li><li><code>locales/*.json</code>: alle Texte, die Spieler sehen.</li><li><code>nay_lib/bridge/custom.lua</code>: dein eigener Framework-Adapter.</li></ul><p>Der restliche Code ist durch Cfx Escrow geschützt.</p><h2 id="verbindet-sich-nay-lib-mit-irgendetwas" tabindex="-1">Verbindet sich nay_lib mit irgendetwas? <a class="header-anchor" href="#verbindet-sich-nay-lib-mit-irgendetwas" aria-label="Permalink to &quot;Verbindet sich nay_lib mit irgendetwas?&quot;">​</a></h2><p>Beim Start liest <code>nay_lib</code> eine öffentliche Versionsdatei (<code>https://versions.nayretis.com/versions.json</code>) und meldet in der Konsole, wenn ein Update verfügbar ist. Mit <code>set nay:versionCheck false</code> schaltest du das ab. Sonst verlässt nichts deinen Server, außer du aktivierst die <a href="/de/nay-lib/api">HTTP-API</a> oder fügst <a href="/de/nay-lib/webhooks">Webhooks</a> hinzu.</p><h2 id="wo-bekomme-ich-hilfe" tabindex="-1">Wo bekomme ich Hilfe? <a class="header-anchor" href="#wo-bekomme-ich-hilfe" aria-label="Permalink to &quot;Wo bekomme ich Hilfe?&quot;">​</a></h2><p>Eröffne einen Beitrag in <code>#support</code> auf dem <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Nayretis Discord</a>, ein Beitrag pro Problem, mit dem Skript und seiner Version, deinem Framework, Inventar und Target sowie den Fehlern aus der Serverkonsole und F8.</p>',18)])])}const f=r(i,[["render",d]]);export{m as __pageData,f as default};
